WITH flagged AS (SELECT *, CASE WHEN txn_time - LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time, id) > INTERVAL '90' DAY THEN 1 ELSE 0 END AS session_start_flag FROM transactions), sessions_transactions AS (SELECT id, account_id, txn_type, amount, txn_time, merchant, SUM(session_start_flag) OVER (PARTITION BY txn_type ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM flagged) SELECT account_id, CASE WHEN session_id >= 7 THEN 'LARGE' ELSE 'SMALL' END AS session_id_tier, ROUND(AVG(amount), 2) AS avg_amount, COUNT(*) FILTER (WHERE txn_type = 'FEE') AS fee_rows, PERCENTILE_APPROX(amount, 0.9) AS amount_p90, RANK() OVER (PARTITION BY account_id ORDER BY COUNT(*) FILTER (WHERE txn_type = 'FEE') DESC) AS fee_rows_rank FROM sessions_transactions GROUP BY account_id, CASE WHEN session_id >= 7 THEN 'LARGE' ELSE 'SMALL' END;
